<section class="dash-card jobs-card" id="jobs"><div class="card-title"><h2>پروژه‌های من</h2><span><?=count($jobs)?> پروژه</span></div><?php foreach($jobs as $job):?><article class="job-item"><div class="job-info"><h3><?=e($job['title'])?></h3><p><?=e(mb_strimwidth($job['description'],0,150,'…'))?></p><small><?=e($job['proposal_count'])?> پیشنهاد · <?=e($job['budget_min'])?> تا <?=e($job['budget_max'])?> دلار</small></div></article><?php endforeach;?><?php if(!$jobs):?><p class="empty-state">هنوز پروژه‌ای منتشر نکرده‌اید.</p><?php endif;?></section>